 function upd(){const b=$('#tabs button.on'),t=b?b.textContent.trim():'';$('#pt').textContent=t||'TMC nazorat';$('#ps').textContent=dt;tabs.querySelectorAll('button').forEach(x=>{if(!x.title)x.title=x.textContent.trim()});
  document.querySelectorAll('svg.rvs:not([data-g])').forEach(s=>{s.dataset.g=1;s.insertAdjacentHTML('afterbegin','<defs><linearGradient id="gAc" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--ac2)"/><stop offset="1" style="stop-color:var(--ac)"/></linearGradient></defs>')})}
